const cfg = $('Continuar sync').first().json;
return [{
  json: {
    ...cfg,
    deposito_id: String(cfg.deposito_id).trim(),
    deposito_resolvido: cfg.deposito_nome || cfg.deposito_id,
    deposito_opcoes: '[]',
  },
}];

const cfg = $('Continuar sync').first().json;
const resp = $input.first().json;

function norm(value) {
  return String(value ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');
}

function depId(dep) {
  return String(dep?.deposito?.id ?? dep?.idDeposito ?? dep?.id ?? '').trim();
}

let depositoId = cfg.deposito_id ? String(cfg.deposito_id).trim() : '';
const want = norm(cfg.deposito_nome ?? 'rajlog');
let depositoResolvido = depositoId;
let depositoOpcoes = [];

if (!depositoId) {
  const row = Array.isArray(resp.data) ? resp.data[0] : null;
  const deps = row?.depositos ?? [];

  depositoOpcoes = deps.map((dep) => ({
    id: depId(dep),
    saldo: Number(dep.saldoFisico ?? dep.saldo ?? 0),
    nome: dep.deposito?.nome ?? dep.deposito?.descricao ?? dep.nome ?? dep.descricao ?? '',
  })).filter((d) => d.id);

  for (const dep of deps) {
    const label = norm(dep.deposito?.nome ?? dep.deposito?.descricao ?? dep.nome ?? dep.descricao ?? '');
    if (!label) continue;
    if (label.includes(want) || want.includes(label)) {
      depositoId = depId(dep);
      depositoResolvido = dep.deposito?.nome ?? dep.nome ?? dep.deposito?.descricao ?? depositoId;
      break;
    }
  }

  if (!depositoId) {
    for (const dep of deps) {
      const raw = String(dep.deposito?.nome ?? dep.nome ?? dep.deposito?.descricao ?? '').toLowerCase();
      if (raw.includes('raj') && raw.includes('log')) {
        depositoId = depId(dep);
        depositoResolvido = raw;
        break;
      }
    }
  }

  const esperado = Number(cfg.deposito_probe_saldo_esperado ?? 0);
  if (!depositoId && esperado > 0) {
    const matches = depositoOpcoes.filter((d) => d.saldo === esperado);
    if (matches.length === 1) {
      depositoId = matches[0].id;
      depositoResolvido = matches[0].nome || `deposito saldo ${esperado}`;
    }
  }
}

const payload = {
  ...cfg,
  deposito_id: depositoId,
  deposito_resolvido: depositoResolvido || cfg.deposito_nome,
  deposito_opcoes: JSON.stringify(depositoOpcoes),
};

if (!depositoId) {
  const err = resp.error ?? null;
  if (err && (err.type === 'TOO_MANY_REQUESTS' || String(err.message ?? '').includes('Limite'))) {
    payload.deposito_erro = `RATE LIMIT BLING no probe. Aguarde 2 minutos, pare outros workflows BLING (vendas/estoque) e rode de novo. ${err.message ?? ''}`;
    payload.rate_limited = true;
  } else if (depositoOpcoes.length) {
    payload.deposito_erro = `RajLog nao identificado. Preencha deposito_id no Config. Opcoes: ${JSON.stringify(depositoOpcoes)}`;
  } else {
    payload.deposito_erro = `Probe sem depositos (produto ${cfg.deposito_probe_external_id ?? '16103416522'}). Resposta: ${JSON.stringify(err ?? resp).slice(0, 400)}`;
  }
}

return [{ json: payload }];

const cfg = $input.first().json;
const limit = Number(cfg.supabase_limit ?? 1000);
const pages = [];
for (let offset = 0; offset < 20000; offset += limit) {
  pages.push({ json: { ...cfg, offset, limit } });
}
return pages;

const all = [];
for (const item of $input.all()) {
  const body = item.json;
  if (Array.isArray(body)) {
    all.push(...body);
  } else if (body?.id && body?.external_id) {
    all.push(body);
  }
}
const unique = [...new Map(all.map((p) => [p.external_id, p])).values()];
return [{ json: { products: unique, total_produtos: unique.length } }];

const products = $input.first().json.products ?? [];
const cfg = $('Paginas supabase').first().json;
const batches = [];
for (let i = 0; i < products.length; i += 30) {
  const chunk = products.slice(i, i + 30);
  const query = chunk.map((p) => `idsProdutos[]=${encodeURIComponent(p.external_id)}`).join('&');
  batches.push({
    json: {
      query,
      map: Object.fromEntries(chunk.map((p) => [String(p.external_id), p.id])),
      bling_base_url: cfg.bling_base_url,
    },
  });
}
if (batches.length === 0) {
  batches.push({ json: { query: '', map: {}, bling_base_url: cfg.bling_base_url, vazio: true } });
}
return batches;

const cfg = $('Paginas supabase').first().json;
const COMPANY_ID = cfg.company_id;
const now = new Date().toISOString();
const depositoId = String(cfg.deposito_id ?? '').trim();
const lotes = $('Lotes estoque').all();
const responses = $input.all();
const stockPayload = [];
const retryMap = {};
let errosApi = 0;
let semDepositos = 0;
let rateLimited = 0;

function depositoKey(dep) {
  return String(dep.deposito?.id ?? dep.idDeposito ?? dep.id ?? dep.depositoId ?? '').trim();
}

function quantityFromRow(row) {
  const direct = row.saldoFisico ?? row.saldo ?? row.quantidade ?? row.saldoVirtual ?? row.saldoFisicoTotal;
  if (direct !== undefined && direct !== null) return Number(direct);
  if (!Array.isArray(row.depositos) || row.depositos.length === 0) return null;
  let quantity = 0;
  let matched = false;
  for (const dep of row.depositos) {
    if (depositoId && depositoKey(dep) !== depositoId) continue;
    matched = true;
    quantity += Number(dep.saldoFisico ?? dep.saldo ?? dep.saldoFisicoTotal ?? 0);
  }
  return matched ? quantity : null;
}

for (let i = 0; i < responses.length; i++) {
  const map = lotes[i]?.json?.map ?? {};
  const item = responses[i].json;
  if (item.error) {
    errosApi += 1;
    if (item.error?.type === 'TOO_MANY_REQUESTS') {
      rateLimited += 1;
      Object.assign(retryMap, map);
    }
    continue;
  }
  const rows = item.data ?? [];
  if (!Array.isArray(rows)) continue;
  for (const row of rows) {
    const externalId = String(row.produto?.id ?? row.idProduto ?? '');
    const productId = map[externalId];
    if (!productId) continue;
    const quantity = quantityFromRow(row);
    if (quantity === null) {
      semDepositos += 1;
      continue;
    }
    stockPayload.push({ company_id: COMPANY_ID, product_id: productId, quantity, updated_at: now });
  }
}

const depositoLabel = cfg.deposito_resolvido || depositoId;
const meta = {
  synced: stockPayload.length,
  erros_api: errosApi,
  rate_limited: rateLimited,
  sem_depositos: semDepositos,
  supabase_url: cfg.supabase_url,
  deposito: depositoLabel,
  deposito_id: depositoId,
  retry_count: Object.keys(retryMap).length,
  skip_post: stockPayload.length === 0,
};

const chunks = [];
for (let i = 0; i < stockPayload.length; i += 50) {
  chunks.push({ json: { body: stockPayload.slice(i, i + 50), ...meta, retry_map: retryMap } });
}
if (chunks.length === 0) {
  chunks.push({ json: { body: [], ...meta, retry_map: retryMap } });
}
return chunks;

const retryMap = $('Montar estoque').first().json.retry_map ?? {};
const cfg = $('Paginas supabase').first().json;
const entries = Object.entries(retryMap);
const batches = [];
for (let i = 0; i < entries.length; i += 20) {
  const chunk = entries.slice(i, i + 20);
  const query = chunk.map(([ext]) => `idsProdutos[]=${encodeURIComponent(ext)}`).join('&');
  batches.push({ json: { query, map: Object.fromEntries(chunk), bling_base_url: cfg.bling_base_url } });
}
if (batches.length === 0) {
  return [{ json: { query: '', map: {}, bling_base_url: cfg.bling_base_url, vazio: true } }];
}
return batches;

const cfg = $('Paginas supabase').first().json;
const COMPANY_ID = cfg.company_id;
const now = new Date().toISOString();
const lotes = $('Lotes retry').all();
const responses = $input.all();
const stockPayload = [];
let errosApi = 0;
let rateLimited = 0;

function quantityFromRow(row) {
  const direct = row.saldoFisico ?? row.saldo ?? row.quantidade ?? row.saldoVirtual ?? row.saldoFisicoTotal;
  if (direct !== undefined && direct !== null) return Number(direct);
  return null;
}

for (let i = 0; i < responses.length; i++) {
  const map = lotes[i]?.json?.map ?? {};
  const item = responses[i].json;
  if (item.error) {
    errosApi += 1;
    if (item.error?.type === 'TOO_MANY_REQUESTS') rateLimited += 1;
    continue;
  }
  const rows = item.data ?? [];
  if (!Array.isArray(rows)) continue;
  for (const row of rows) {
    const externalId = String(row.produto?.id ?? row.idProduto ?? '');
    const productId = map[externalId];
    if (!productId) continue;
    const quantity = quantityFromRow(row);
    if (quantity === null) continue;
    stockPayload.push({ company_id: COMPANY_ID, product_id: productId, quantity, updated_at: now });
  }
}

const chunks = [];
for (let i = 0; i < stockPayload.length; i += 50) {
  chunks.push({ json: { body: stockPayload.slice(i, i + 50), synced: stockPayload.length, rate_limited: rateLimited, erros_api: errosApi, supabase_url: cfg.supabase_url, skip_post: stockPayload.length === 0 } });
}
if (chunks.length === 0) {
  chunks.push({ json: { body: [], synced: 0, rate_limited: rateLimited, erros_api: errosApi, supabase_url: cfg.supabase_url, skip_post: true } });
}
return chunks;

const m1 = $('Montar estoque').first().json;
let retrySynced = 0;
let retryRate = 0;

try {
  const m2 = $('Montar retry').first()?.json;
  if (m2) {
    retrySynced = m2.synced ?? 0;
    retryRate = m2.rate_limited ?? 0;
  }
} catch (e) {}

const totalSynced = (m1.synced ?? 0) + retrySynced;
const rateLeft = retryRate > 0 ? retryRate : (retrySynced > 0 ? 0 : (m1.rate_limited ?? 0));

return [{
  json: {
    produtos_supabase: $('Consolidar produtos').first().json.total_produtos,
    estoque_sincronizado: totalSynced,
    erros_api: m1.erros_api ?? 0,
    deposito_id: m1.deposito_id,
    deposito: m1.deposito,
    sem_depositos: m1.sem_depositos ?? 0,
    rate_limited: rateLeft,
    retry_sincronizado: retrySynced,
    produtos_pendentes_retry: m1.retry_count ?? 0,
    deposito_erro: rateLeft > 0 ? 'Ainda houve rate limit — aguarde 2 min e rode de novo' : '',
    abortado: false,
  },
}];
